#[test]
fn the_sort_is_numpy_s_quicksort_index_for_index() {
    let vectors: serde_json::Value = serde_json::from_str(VECTORS).unwrap();
    let mut checked = 0;
    for vector in vectors.as_array().unwrap() {
        if let Some(values) = vector.get("v") {
            let values: Vec<i64> = serde_json::from_value(values.clone()).unwrap();
            let order: Vec<usize> = serde_json::from_value(vector["order"].clone()).unwrap();
            assert_eq!(introsort_argsort(&values), order, "{} values", values.len());
            checked += 1;
        } else {
            let given: Vec<Option<i64>> =
                serde_json::from_value(vector["desc_in"].clone()).unwrap();
            let order: Vec<usize> = serde_json::from_value(vector["desc"].clone()).unwrap();
            assert_eq!(descending_order(&given), order);
            checked += 1;
        }
    }
    assert_eq!(checked, 5);
}

#[test]
fn a_sort_past_its_depth_limit_still_sorts() {
    // An organ-pipe array drives median-of-three quicksort deep; whatever
    // path it takes, the result is ordered and a permutation.
    let mut values: Vec<i64> = (0..512).chain((0..512).rev()).collect();
    values.extend((0..300).map(|i| (i * 7919) % 101));
    let order = introsort_argsort(&values);
    let mut seen = order.clone();
    seen.sort_unstable();
    assert_eq!(seen, (0..values.len()).collect::<Vec<_>>());
    assert!(order.windows(2).all(|w| values[w[0]] <= values[w[1]]));
}
